<?php

declare(strict_types=1);

namespace Aldytoi\LaravelToi\View\Components;

use Illuminate\View\Component;

class LucideIcon extends Component
{
    public function __construct(
        public string $name,
        public string $class = '',
    ) {}

    public function render()
    {
        return function (array $data) {
            $svg = $this->getSvg($data['name'] ?? $this->name);

            if (!empty($data['attributes'] ?? '')) {
                $svg = str_replace('<svg', '<svg ' . $data['attributes'], $svg);
            }

            if (!empty($this->class)) {
                $svg = str_replace('<svg', '<svg class="' . e($this->class) . '"', $svg);
            }

            return $svg;
        };
    }

